package com.bank.cost;

public class CloudResource {
    public enum Kind { COMPUTE, STORAGE }

    private final String id;
    private final Kind kind;
    private final String environment;     // prod, dev, staging
    private final double avgCpuPercent;   // for compute
    private final boolean interruptible;  // batch/stateless worker?
    private final boolean alwaysOn;       // steady baseline?
    private final int daysSinceAccess;    // for storage

    public CloudResource(String id, Kind kind, String environment, double avgCpuPercent,
                         boolean interruptible, boolean alwaysOn, int daysSinceAccess) {
        this.id = id; this.kind = kind; this.environment = environment;
        this.avgCpuPercent = avgCpuPercent; this.interruptible = interruptible;
        this.alwaysOn = alwaysOn; this.daysSinceAccess = daysSinceAccess;
    }

    public String getId() { return id; }
    public Kind getKind() { return kind; }
    public String getEnvironment() { return environment; }
    public double getAvgCpuPercent() { return avgCpuPercent; }
    public boolean isInterruptible() { return interruptible; }
    public boolean isAlwaysOn() { return alwaysOn; }
    public int getDaysSinceAccess() { return daysSinceAccess; }
    public boolean isProd() { return "prod".equalsIgnoreCase(environment); }
}
