package com.bank.cost;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class CostOptimizer {
    private static final Logger log = Logger.getLogger(CostOptimizer.class.getName());

    public List<CostRecommendation> analyze(List<CloudResource> resources) {
        List<CostRecommendation> recs = new ArrayList<>();
        for (CloudResource r : resources) {
            if (r.getKind() == CloudResource.Kind.COMPUTE) {
                // Non-prod idle at night → scheduled shutdown (safe: not prod).
                if (!r.isProd()) {
                    recs.add(rec(r, "SCHEDULED_SHUTDOWN",
                        "Non-prod (" + r.getEnvironment() + "): stop nights/weekends via "
                        + "EventBridge+Lambda — ~65% saving, zero prod impact."));
                }
                // Always-on steady baseline → Savings Plan (protects performance).
                if (r.isAlwaysOn() && r.isProd()) {
                    recs.add(rec(r, "SAVINGS_PLAN",
                        "Always-on prod baseline: 1-yr Compute Savings Plan — discount with "
                        + "NO capacity reduction, performance unchanged."));
                }
                // Interruptible batch → Spot (fault tolerant).
                if (r.isInterruptible()) {
                    recs.add(rec(r, "SPOT",
                        "Interruptible batch: run on Spot (~70-90% off); reschedule on reclaim."));
                }
                // Low utilization → right-size (keep headroom).
                if (r.getAvgCpuPercent() < 20) {
                    recs.add(rec(r, "RIGHT_SIZE",
                        "avg CPU " + r.getAvgCpuPercent() + "% — step down one size, keep 2x "
                        + "headroom over peak; re-measure to confirm performance holds."));
                }
            } else { // STORAGE
                if (r.getDaysSinceAccess() > 30) {
                    recs.add(rec(r, "STORAGE_TIERING",
                        "Not accessed in " + r.getDaysSinceAccess() + " days: lifecycle rule "
                        + "Standard→IA→Glacier; data retained, big saving, no perf hit."));
                }
            }
        }
        return recs;
    }

    private CostRecommendation rec(CloudResource r, String lever, String why) {
        log.info(() -> "  [" + lever + "] " + r.getId() + " — " + why);
        return new CostRecommendation(r.getId(), lever, why);
    }
}
