package com.bank.cost;

import java.util.List;
import java.util.logging.*;

public class CostOptimizationDemo {
    private static final Logger log = Logger.getLogger(CostOptimizationDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        List<CloudResource> resources = List.of(
            new CloudResource("i-prod-api",    CloudResource.Kind.COMPUTE, "prod",    55, false, true,  0),
            new CloudResource("i-dev-sandbox", CloudResource.Kind.COMPUTE, "dev",     8,  false, false, 0),
            new CloudResource("i-batch-settle",CloudResource.Kind.COMPUTE, "prod",    30, true,  false, 0),
            new CloudResource("i-report-gen",  CloudResource.Kind.COMPUTE, "staging", 12, false, false, 0),
            new CloudResource("s3-statements", CloudResource.Kind.STORAGE, "prod",    0,  false, false, 120));

        log.info("National Bank of India — idle-resource cost review");
        CostOptimizer optimizer = new CostOptimizer();
        List<CostRecommendation> recs = optimizer.analyze(resources);
        log.info(() -> "Generated " + recs.size() + " recommendations (none reduce prod capacity).");
    }
}
